use tfhe::prelude::*;
use tfhe::{generate_keys, unset_server_key, ConfigBuilder, FheUint8};

pub fn increment(value: u8) -> u8 {
    let (client, _server) = generate_keys(ConfigBuilder::default().build());
    unset_server_key(); // No server key remains in this execution thread.
    let encrypted = FheUint8::encrypt(value, &client);
    let result = encrypted + 1u8;
    result.decrypt(&client)
}

use tfhe::prelude::*;
use tfhe::{generate_keys, set_server_key, unset_server_key, ConfigBuilder, FheUint8};

pub fn increment(value: u8) -> u8 {
    let (client, server) = generate_keys(ConfigBuilder::default().build());
    unset_server_key();
    set_server_key(server);
    let encrypted = FheUint8::encrypt(value, &client);
    let result = encrypted + 1u8;
    result.decrypt(&client)
}

#include "openfhe.h"
inline int64_t roundtrip(int64_t value) {
    using namespace lbcrypto;
    CCParams<CryptoContextBFVRNS> params;
    params.SetPlaintextModulus(65537);
    params.SetMultiplicativeDepth(1);
    params.SetSecurityLevel(HEStd_128_classic);
    auto cc = GenCryptoContext(params);
    auto keys = cc->KeyGen();
    auto cipher = cc->Encrypt(keys.publicKey, cc->MakePackedPlaintext({value}));
    Plaintext plain;
    auto result = cc->Decrypt(keys.secretKey, cipher, &plain);
    if (!result.isValid || !plain) throw std::runtime_error("decryption failed");
    plain->SetLength(1);
    return plain->GetPackedValue().at(0);
}

#include "openfhe.h"
inline int64_t roundtrip(int64_t value) {
    using namespace lbcrypto;
    CCParams<CryptoContextBFVRNS> params;
    params.SetPlaintextModulus(65537);
    params.SetMultiplicativeDepth(1);
    params.SetSecurityLevel(HEStd_128_classic);
    auto cc = GenCryptoContext(params);
    cc->Enable(PKE);
    auto keys = cc->KeyGen();
    auto cipher = cc->Encrypt(keys.publicKey, cc->MakePackedPlaintext({value}));
    Plaintext plain;
    auto result = cc->Decrypt(keys.secretKey, cipher, &plain);
    if (!result.isValid || !plain) throw std::runtime_error("decryption failed");
    plain->SetLength(1);
    return plain->GetPackedValue().at(0);
}
